from contextlib import contextmanager


class NPUModelRunner310(NPUModelRunner):

    def __init__(self, vllm_config, ...):
        super().__init__(vllm_config, ...)
        self._need_patch_uniform_decode = (
            self.graph_uniform_decode_query_len != self.uniform_decode_query_len
        )

    @contextmanager
    def _patch_uniform_decode(self):
        old = self.uniform_decode_query_len
        self.uniform_decode_query_len = self.cudagraph_dispatcher.uniform_decode_query_len
        try:
            yield
        finally:
            self.uniform_decode_query_len = old

    def _dummy_run(self, num_tokens, ...):
        if self._need_patch_uniform_decode:
            with self._patch_uniform_decode():
                self._check_and_update_cudagraph_mode(...)
                return super()._dummy_run(num_tokens=num_tokens, ...)
        else:
            self._check_and_update_cudagraph_mode(...)
            return super()._dummy_run(num_tokens=num_tokens, ...)
